-- =====================================================================
-- Run this ONCE, after the database is built and the "notify" function exists (guide, Step 7).
-- You normally do NOT edit this file: the setup helper (guide, Step 3) gives you a ready-to-paste copy.
-- If you edit by hand, replace these three words everywhere:
--   YOUR-PROJECT-REF   ->  the part of your project web address before .supabase.co
--   YOUR-CRON-SECRET   ->  the CRON_SECRET you saved in Supabase (guide, Step 6)
--   YOUR-PUBLIC-KEY    ->  your Supabase PUBLISHABLE key (the public one, never the secret key)
-- When it works, the last line shows a table with two rows: rb-deliver and rb-morning.
-- =====================================================================
create extension if not exists pg_net with schema extensions;
create extension if not exists pg_cron with schema pg_catalog;
grant usage on schema cron to postgres;
grant all privileges on all tables in schema cron to postgres;

-- Wakes the delivery function, but only when something is waiting to be sent.
create or replace function public.rb_deliver_waiting() returns void language plpgsql security definer set search_path = public as $f$
begin
  if exists (select 1 from public.notifications where sent_at is null) then
    perform net.http_post(
      url := 'https://YOUR-PROJECT-REF.supabase.co/functions/v1/notify',
      headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', 'YOUR-CRON-SECRET',
                                    'apikey', 'YOUR-PUBLIC-KEY', 'Authorization', 'Bearer YOUR-PUBLIC-KEY'),
      body := '{}'::jsonb,
      timeout_milliseconds := 30000);
  end if;
end $f$;
revoke execute on function public.rb_deliver_waiting() from public, anon, authenticated;

select cron.unschedule(jobid) from cron.job where jobname in ('rb-morning', 'rb-deliver');
-- Every morning at 8:00 AM India time (02:30 UTC): make the month's bills, queue reminders and the owner's summary.
select cron.schedule('rb-morning', '30 2 * * *', 'select public.generate_reminders()');
-- Every 10 minutes: send whatever is waiting to phones and email.
select cron.schedule('rb-deliver', '*/10 * * * *', 'select public.rb_deliver_waiting()');

-- Proof that both jobs exist:
select jobname, schedule, active from cron.job where jobname in ('rb-morning', 'rb-deliver') order by jobname;
